        // Senior partition: 60+ (test 70)
        // Adult partition: 26-59 (test 40)
        // Child partition: 0-17 (test 10)
    }

    private boolean isEligibleForDiscount(int age) {
        return (age >= 18 && age <= 25) || age >= 60;
    }
