import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate, Trend } from 'k6/metrics';

export let errorRate = new Rate('errors');
export let responseTimeTrend = new Trend('response_time');

export let options = {
  stages: [
    { duration: '1m', target: 50 },   // Ramp-up to 50 users
    { duration: '3m', target: 50 },   // Stay at 50 users
    { duration: '1m', target: 100 },  // Ramp-up to 100 users
    { duration: '3m', target: 100 },  // Stay at 100 users
    { duration: '1m', target: 200 },  // Ramp-up to 200 users
    { duration: '3m', target: 200 },  // Stay at 200 users
    { duration: '1m', target: 0 },    // Ramp-down to 0
  ],
  thresholds: {
    http_req_duration: ['p95<500'],   // 95% of requests must complete below 500ms
    http_req_failed: ['rate<0.01'],   // Less than 1% of requests can fail
    'response_time': ['avg<300'],      // Average response time < 300ms
  },
};

export default function() {
  let baseURL = 'https://api.example.com/v1';

  // Login request
  let loginPayload = JSON.stringify({
    username: `user${__VU}@example.com`,  // Virtual user ID
    password: 'testpass123'
  });

  let loginParams = {
    headers: {
      'Content-Type': 'application/json',
    },
  };

  let loginRes = http.post(`${baseURL}/auth/login`, loginPayload, loginParams);

  check(loginRes, {
    'login status is 200': (r) => r.status === 200,
    'login has token': (r) => r.json('token') !== undefined,
  }) || errorRate.add(1);

  responseTimeTrend.add(loginRes.timings.duration);

  // Extract token
  let authToken = loginRes.json('token');

  // Search products
  let searchParams = {
    headers: {
      'Authorization': `Bearer ${authToken}`,
    },
  };

  let searchRes = http.get(
    `${baseURL}/products/search?q=laptop&page=1&limit=20`,
    searchParams
  );

  check(searchRes, {
    'search status is 200': (r) => r.status === 200,
    'search has results': (r) => r.json('products').length > 0,
  }) || errorRate.add(1);

  // Add to cart
  let cartPayload = JSON.stringify({
    productId: 'prod-123',
    quantity: 1
  });

  let cartRes = http.post(
    `${baseURL}/cart/items`,
    cartPayload,
    { headers: { 'Authorization': `Bearer ${authToken}`, 'Content-Type': 'application/json' } }
  );

  check(cartRes, {
    'add to cart status is 200': (r) => r.status === 200,
    'cart updated': (r) => r.json('items').length > 0,
  }) || errorRate.add(1);

  // Think time - simulate user reading
  sleep(Math.random() * 3 + 1); // 1-4 seconds
}

export function handleSummary(data) {
  return {
    'summary.json': JSON.stringify(data),
    'thresholds.txt': Object.entries(data.metrics)
      .filter(([_, metric]) => metric.thresholds)
      .map(([name, metric]) => `${name}: ${JSON.stringify(metric.thresholds)}`)
      .join('\n'),
  };
}

