import static org.junit.jupiter.api.Assertions.assertTrue;

public class AndroidAppTest {
    private AppiumDriver<MobileElement> driver;

    @BeforeEach
    public void setUp() throws Exception {
        DesiredCapabilities capabilities = new DesiredCapabilities();

        // Platform capabilities
        capabilities.setCapability(MobileCapabilityType.PLATFORM_NAME, "Android");
        capabilities.setCapability(MobileCapabilityType.PLATFORM_VERSION, "12.0");
        capabilities.setCapability(MobileCapabilityType.DEVICE_NAME, "Pixel 4");
        capabilities.setCapability(MobileCapabilityType.UDID, "emulator-5554");

        // App capabilities
        capabilities.setCapability("appPackage", "com.example.myapp");
        capabilities.setCapability("appActivity", "com.example.myapp.MainActivity");
        capabilities.setCapability("noReset", false);

        // Network capabilities
        capabilities.setCapability("networkSpeed", "full");

        driver = new AndroidDriver<>(new URL("http://127.0.0.1:4723/wd/hub"), capabilities);
        driver.manage().timeouts().implicitlyWait(10, TimeUnit.SECONDS);
    }

    @Test
    public void testLoginFlow() {
        // Find and interact with elements
        MobileElement usernameField = driver.findElementById("com.example.myapp:id/username");
        MobileElement passwordField = driver.findElementById("com.example.myapp:id/password");
        MobileElement loginButton = driver.findElementById("com.example.myapp:id/login");

        usernameField.sendKeys("testuser");
        passwordField.sendKeys("Test@123");
        loginButton.click();

        // Verify successful login
        MobileElement dashboardElement = driver.findElementById("com.example.myapp:id/dashboard");
        assertTrue(dashboardElement.isDisplayed());

        // Handle native gestures
        driver.findElementById("com.example.myapp:id/menu").click();

        // Swipe gesture
        MobileElement scrollView = driver.findElementById("com.example.myapp:id/scrollView");
        driver.swipe(100, 500, 100, 100, 1000);

        // Handle alerts
        driver.switchTo().alert().accept();
    }

    @Test
    public void testInterruptionHandling() throws InterruptedException {
        // Test during incoming call
        driver.findElementById("com.example.myapp:id/startVideo").click();

        // Simulate incoming call (using ADB)
        Runtime.getRuntime().exec("adb shell am start -a android.intent.action.CALL -d tel:5551234");
        Thread.sleep(5000);

        // Verify app state after call ends
        Runtime.getRuntime().exec("adb shell input keyevent KEYCODE_ENDCALL");
        Thread.sleep(2000);

        MobileElement videoScreen = driver.findElementById("com.example.myapp:id/videoView");
        assertTrue(videoScreen.isDisplayed());
    }

    @Test
    public void testNetworkConditions() {
        // Test on different network speeds
        setNetworkSpeed("edge"); // 2G
        long startTime = System.currentTimeMillis();
        driver.findElementById("com.example.myapp:id/loadData").click();
        long endTime = System.currentTimeMillis();
        assertTrue((endTime - startTime) < 10000, "Load time exceeded 10s on 2G");

        setNetworkSpeed("lte"); // 4G
        startTime = System.currentTimeMillis();
        driver.findElementById("com.example.myapp:id/loadData").click();
        endTime = System.currentTimeMillis();
        assertTrue((endTime - startTime) < 2000, "Load time exceeded 2s on 4G");

        // Test offline mode
        setNetworkSpeed("gsm"); // Disconnect
        driver.findElementById("com.example.myapp:id/loadData").click();
        MobileElement errorMessage = driver.findElementById("com.example.myapp:id/errorMessage");
        assertTrue(errorMessage.getText().contains("No network connection"));
    }

