    @Test
    public void testBatteryImpact() {
        // Measure battery usage before test
        double batteryBefore = getBatteryLevel();

        // Perform intensive operations
        for (int i = 0; i < 10; i++) {
            driver.findElementById("com.example.myapp:id/performIntensiveTask").click();
            driver.wait(5000);
        }

        // Measure battery after test
        double batteryAfter = getBatteryLevel();
