    await element(by.id('usernameInput')).typeText('testuser');
    await element(by.id('passwordInput')).typeText('Test@123');
    await element(by.id('loginButton')).tap();

    await expect(element(by.id('dashboard'))).toBeVisible();
    await expect(element(by.text('Welcome, testuser!'))).toBeVisible();
  });

  it('should handle network interruptions', async () => {
    await element(by.id('loginButton')).tap();

    // Simulate network loss
    await device.setURLBlacklist(['.*']);

    await element(by.id('loadData')).tap();
    await expect(element(by.id('errorMessage'))).toBeVisible();
    await expect(element(by.text('Network error'))).toBeVisible();

    // Restore network
    await device.setURLBlacklist([]);
    await element(by.id('retryButton')).tap();
    await expect(element(by.id('dataLoaded'))).toBeVisible();
  });

  it('should handle interruption during checkout', async () => {
    await element(by.id('addToCart')).tap();
    await element(by.id('checkout')).tap();

    // Simulate incoming call
    await device.sendToHome();
    await device.launchApp({ newInstance: false });

    // Verify app state preserved
    await expect(element(by.id('checkoutScreen'))).toBeVisible();
    await expect(element(by.id('cartItems'))).toHaveLength(1);
  });

  it('should work offline', async () => {
    await device.setStatusBar({ network: 'none' });

    await element(by.id('viewOfflineContent')).tap();
    await expect(element(by.id('cachedContent'))).toBeVisible();

    await device.setStatusBar({ network: 'wifi' });
  });

  it('should handle orientation changes', async () => {
    await element(by.id('viewProduct')).tap();

    await device.setOrientation('landscape');
    await expect(element(by.id('productImage'))).toBeVisible();

    await device.setOrientation('portrait');
    await expect(element(by.id('productImage'))).toBeVisible();
  });

  it('should respect memory limits', async () => {
    // Load many images
    for (let i = 0; i < 50; i++) {
      await element(by.id('loadMore')).tap();
    }

    // Check memory warning
    const memoryWarning = await device.getMemoryWarningLevel();
    expect(memoryWarning).not.toBe('CRITICAL');
  });
});
